// UiFactory — builds UGUI + TextMeshPro UI in code (no hand-written scene data).
// All screens use these helpers, so the UI is deterministic and batchmode-safe.
// Text uses the CJK font asset (Noto Sans CJK SC, generated by Editor/BuildScript
// into Resources/Fonts/); falls back to TMP's default font if it is missing.
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.Events;
using TMPro;

namespace GalgameOnline.UI
{
    public static class UiFactory
    {
        // ---- Ultramarine visual system (project art direction) ----
        // Deep, quiet, romantic, mysterious, elegant, dreamy Japanese
        // fantasy. Main: deep ultramarine #142B67, classic ultramarine
        // #244DAB, starry blue #4169C9, moonlight blue #7897DB.
        // Accents: moon white #E5EAF7, sakura pink #DDAFCB (sparingly),
        // silver white #C9D4E8. No cyberpunk, no fluorescent blue, no
        // cheap purple-blue gradients.
        public static readonly Color DeepUltramarine = new Color(0.078f, 0.169f, 0.404f, 1f);    // #142B67
        public static readonly Color ClassicUltramarine = new Color(0.141f, 0.302f, 0.671f, 1f); // #244DAB
        public static readonly Color StarryBlue = new Color(0.255f, 0.412f, 0.788f, 1f);         // #4169C9
        public static readonly Color MoonlightBlue = new Color(0.471f, 0.592f, 0.859f, 1f);      // #7897DB
        public static readonly Color MoonWhite = new Color(0.898f, 0.918f, 0.969f, 1f);           // #E5EAF7
        public static readonly Color SakuraPink = new Color(0.867f, 0.686f, 0.796f, 1f);          // #DDAFCB
        public static readonly Color SilverWhite = new Color(0.788f, 0.831f, 0.910f, 1f);         // #C9D4E8
        public static readonly Color SilverBorder = new Color(0.788f, 0.831f, 0.910f, 0.55f);     // hairline
        public static readonly Color DeepRose = new Color(0.45f, 0.20f, 0.30f, 1f);               // logout / danger
        public static readonly Color PaleGold = new Color(0.851f, 0.796f, 0.667f, 1f);             // #D9CBAA (accent)

        /// <summary>Deep-ultramarine glass: semi-transparent so background
        /// art (shrine / sakura / moon) shows through faintly.</summary>
        public static Color Glass(float alpha = 0.88f)
            => new Color(0.078f, 0.169f, 0.404f, alpha);

        /// <summary>Moon-white glass for input fields and cards.</summary>
        public static Color GlassWhite(float alpha = 0.08f)
            => new Color(0.898f, 0.918f, 0.969f, alpha);

        // ---- Runtime-generated art (soft shapes, glows, gradients) ----
        // UGUI has no built-in rounded rectangles or radial gradients, so
        // these textures are drawn once in code and cached. They replace the
        // stiff rectangular panels and the hard-edged white moon disc.

        private static Sprite _roundedSprite;

        /// <summary>White rounded-rectangle sprite for 9-slice (Sliced) images.
        /// 256px texture, 24px corner radius: the corner is ~9% of the rect,
        // so cards, buttons and bars get soft corners without going pill-shaped.</summary>
        public static Sprite RoundedSprite
        {
            get
            {
                if (_roundedSprite != null) return _roundedSprite;
                const int s = 256, r = 24;
                var tex = new Texture2D(s, s, TextureFormat.RGBA32, false);
                var cols = new Color[s * s];
                float half = s / 2f;
                for (int y = 0; y < s; y++)
                {
                    for (int x = 0; x < s; x++)
                    {
                        // Signed distance to the rounded rect (negative inside).
                        float qx = Mathf.Abs(x + 0.5f - half) - (half - r);
                        float qy = Mathf.Abs(y + 0.5f - half) - (half - r);
                        float ax = Mathf.Max(qx, 0f), ay = Mathf.Max(qy, 0f);
                        float d = Mathf.Sqrt(ax * ax + ay * ay) + Mathf.Min(Mathf.Max(qx, qy), 0f) - r;
                        float a = Mathf.Clamp01(0.5f - d); // 1px antialiased edge
                        cols[y * s + x] = new Color(1f, 1f, 1f, a);
                    }
                }
                tex.SetPixels(cols);
                tex.Apply();
                _roundedSprite = Sprite.Create(tex, new Rect(0, 0, s, s),
                    new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect,
                    new Vector4(r, r, r, r));
                return _roundedSprite;
            }
        }

        /// <summary>Like Panel, but with soft rounded corners (Sliced).</summary>
        public static GameObject RoundedPanel(Transform parent, string name,
            Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Color bg)
        {
            var go = Panel(parent, name, anchorMin, anchorMax, size, bg);
            var img = go.GetComponent<Image>();
            img.sprite = RoundedSprite;
            img.type = Image.Type.Sliced;
            return go;
        }

        private static Texture2D _radialGlowTex;
        private static Sprite _radialGlowSprite;

        /// <summary>Soft radial glow: bright white centre fading smoothly to
        // transparent at the edge. Tint it with the Image colour for halos,
        // ambient light and stardust dots.</summary>
        public static Sprite RadialGlowSprite()
        {
            if (_radialGlowSprite != null) return _radialGlowSprite;
            const int s = 256;
            var tex = new Texture2D(s, s, TextureFormat.RGBA32, false);
            var cols = new Color[s * s];
            for (int y = 0; y < s; y++)
            {
                for (int x = 0; x < s; x++)
                {
                    float dx = (x + 0.5f) / s - 0.5f;
                    float dy = (y + 0.5f) / s - 0.5f;
                    float r = Mathf.Sqrt(dx * dx + dy * dy) * 2f; // 0 centre, 1 edge
                    float a = Mathf.Clamp01(1f - r);
                    a = a * a;
                    cols[y * s + x] = new Color(1f, 1f, 1f, a);
                }
            }
            tex.SetPixels(cols);
            tex.Apply();
            _radialGlowTex = tex;
            _radialGlowSprite = Sprite.Create(tex, new Rect(0, 0, s, s), new Vector2(0.5f, 0.5f));
            return _radialGlowSprite;
        }

        private static Sprite _moonDiscSprite;

        /// <summary>A moon disc with a soft edge band instead of a hard circle:
        // solid inside, fading out over the outer ~18% so it melts into the
        // night sky instead of sitting on it like a white sticker.</summary>
        public static Sprite MoonDiscSprite()
        {
            if (_moonDiscSprite != null) return _moonDiscSprite;
            const int s = 256;
            var tex = new Texture2D(s, s, TextureFormat.RGBA32, false);
            var cols = new Color[s * s];
            for (int y = 0; y < s; y++)
            {
                for (int x = 0; x < s; x++)
                {
                    float dx = (x + 0.5f) / s - 0.5f;
                    float dy = (y + 0.5f) / s - 0.5f;
                    float r = Mathf.Sqrt(dx * dx + dy * dy) * 2f;
                    float a = 1f - Mathf.SmoothStep(0.62f, 0.80f, r);
                    float shade = 1f - 0.05f * r;
                    cols[y * s + x] = new Color(0.93f * shade, 0.95f * shade, 1f * shade, a);
                }
            }
            tex.SetPixels(cols);
            tex.Apply();
            _moonDiscSprite = Sprite.Create(tex, new Rect(0, 0, s, s), new Vector2(0.5f, 0.5f));
            return _moonDiscSprite;
        }

        private static readonly Dictionary<string, Sprite> _gradientSprites = new Dictionary<string, Sprite>();

        /// <summary>Vertical gradient sprite (1x256 texture, bottom colour at
        // y=0). Used for the screen backdrop so the background has depth
        // instead of a flat solid colour.</summary>
        public static Sprite GradientSprite(Color top, Color bottom)
        {
            string key = ((Color32)top).r + "," + ((Color32)top).g + "," + ((Color32)top).b
                + "|" + ((Color32)bottom).r + "," + ((Color32)bottom).g + "," + ((Color32)bottom).b;
            if (_gradientSprites.TryGetValue(key, out var cached)) return cached;
            const int h = 256;
            var tex = new Texture2D(1, h, TextureFormat.RGBA32, false);
            var cols = new Color[h];
            for (int y = 0; y < h; y++)
                cols[y] = Color.Lerp(bottom, top, (float)y / (h - 1));
            tex.SetPixels(cols);
            tex.Apply();
            var sprite = Sprite.Create(tex, new Rect(0, 0, 1, h), new Vector2(0.5f, 0.5f));
            _gradientSprites[key] = sprite;
            return sprite;
        }

        private static TMP_FontAsset _cjkFont;
        private static bool _fontTried;
        private static Material _uiMaterial;
        private static bool _uiMaterialTried;

        /// <summary>Material that references the built-in UI/Default shader.
        /// The UGUI package cache has no runtime UI shaders, so a player
        /// build would otherwise render every Image magenta. Baked by
        /// BuildScript.GenerateUiMaterial into Resources/UI/; null in the
        /// Editor (where the built-in default works) if it was never generated.
        /// </summary>
        public static Material UiMaterial
        {
            get
            {
                if (!_uiMaterialTried)
                {
                    _uiMaterialTried = true;
                    _uiMaterial = Resources.Load<Material>("UI/DefaultUIMaterial");
                }
                return _uiMaterial;
            }
        }

        private static void ApplyMaterial(Image img)
        {
            var m = UiMaterial;
            if (m != null) img.material = m;
        }

        /// <summary>1px silver-white hairline frame around a rect (glass edge).
        /// Four thin Images pinned to the rect's edges, drawn above the fill.</summary>
        public static void AddSilverBorder(RectTransform rt, float thickness = 1f)
        {
            AddBorderEdge(rt, "BorderTop", new Vector2(0, 1), new Vector2(1, 1),
                new Vector2(0, -thickness), Vector2.zero, thickness);
            AddBorderEdge(rt, "BorderBottom", new Vector2(0, 0), new Vector2(1, 0),
                Vector2.zero, new Vector2(0, thickness), thickness);
            AddBorderEdge(rt, "BorderLeft", new Vector2(0, 0), new Vector2(0, 1),
                Vector2.zero, new Vector2(thickness, 0), thickness);
            AddBorderEdge(rt, "BorderRight", new Vector2(1, 0), new Vector2(1, 1),
                new Vector2(-thickness, 0), Vector2.zero, thickness);
        }

        private static void AddBorderEdge(RectTransform parent, string name,
            Vector2 anchorMin, Vector2 anchorMax, Vector2 offsetMin, Vector2 offsetMax, float thickness)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var rt = go.AddComponent<RectTransform>();
            rt.anchorMin = anchorMin;
            rt.anchorMax = anchorMax;
            rt.offsetMin = offsetMin;
            rt.offsetMax = offsetMax;
            var img = go.AddComponent<Image>();
            img.color = SilverBorder;
            ApplyMaterial(img);
        }

        /// <summary>Full-screen background: art from Resources/Backgrounds/&lt;name&gt;
        /// (shrine / sakura / moon) if present, else the solid deep-ultramarine
        /// glass colour. Call before building the screen's root panel, so the
        /// panel's translucency lets the art show through.</summary>
        public static void AddBackground(Transform canvas, string artName, Color fallback)
        {
            var go = new GameObject("Background");
            go.transform.SetParent(canvas, false);
            var rt = go.AddComponent<RectTransform>();
            Stretch(rt);
            var img = go.AddComponent<Image>();
            var sprite = Resources.Load<Sprite>("Backgrounds/" + artName);
            if (sprite != null)
            {
                img.sprite = sprite;
                img.color = Color.white;
            }
            else
            {
                img.color = fallback;
            }
            ApplyMaterial(img);
        }

        /// <summary>Creates an Image showing a runtime sprite (e.g. character
        /// art loaded from Resources), with the baked UI material applied so
        /// it never renders magenta. Returns null if sprite is null.</summary>
        public static Image ArtImage(Transform parent, string name, Sprite sprite, bool preserveAspect = true)
        {
            if (sprite == null) return null;
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var img = go.AddComponent<Image>();
            img.sprite = sprite;
            img.preserveAspect = preserveAspect;
            img.color = Color.white;
            ApplyMaterial(img);
            return img;
        }

        public static TMP_FontAsset CjkFont
        {
            get
            {
                if (!_fontTried)
                {
                    _fontTried = true;
                    _cjkFont = Resources.Load<TMP_FontAsset>("Fonts/NotoSansCJKsc SDF");
                }
                return _cjkFont;
            }
        }

        public static void ApplyFont(TextMeshProUGUI tmp)
        {
            if (CjkFont != null) tmp.font = CjkFont;
        }

        public static void Stretch(RectTransform rt)
        {
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.offsetMin = Vector2.zero;
            rt.offsetMax = Vector2.zero;
        }

        public static GameObject Panel(Transform parent, string name,
            Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Color bg)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var rt = go.AddComponent<RectTransform>();
            rt.anchorMin = anchorMin;
            rt.anchorMax = anchorMax;
            rt.sizeDelta = size;
            var img = go.AddComponent<Image>();
            img.color = bg;
            ApplyMaterial(img);
            return go;
        }

        public static TextMeshProUGUI Label(Transform parent, string name, string text,
            int fontSize, TextAlignmentOptions align, Color color, bool bold = false)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var tmp = go.AddComponent<TextMeshProUGUI>();
            tmp.text = text;
            tmp.fontSize = fontSize;
            tmp.alignment = align;
            tmp.color = color;
            tmp.fontStyle = bold ? FontStyles.Bold : FontStyles.Normal;
            ApplyFont(tmp);
            var rt = go.GetComponent<RectTransform>();
            rt.anchorMin = new Vector2(0, 1);
            rt.anchorMax = new Vector2(0, 1);
            rt.pivot = new Vector2(0, 1);
            rt.sizeDelta = new Vector2(600, 40);
            return tmp;
        }

        public static void Place(RectTransform rt, float x, float y, float w, float h)
        {
            rt.anchoredPosition = new Vector2(x, y);
            rt.sizeDelta = new Vector2(w, h);
        }

        public static Button Button(Transform parent, string name, string label,
            UnityAction onClick, Vector2 size, Color? bg = null)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var rt = go.AddComponent<RectTransform>();
            rt.sizeDelta = size;
            var img = go.AddComponent<Image>();
            img.color = bg ?? ClassicUltramarine;
            ApplyMaterial(img);
            AddSilverBorder(rt);
            var btn = go.AddComponent<Button>();
            btn.onClick.AddListener(onClick);
            var colors = btn.colors;
            colors.highlightedColor = StarryBlue;
            colors.pressedColor = DeepUltramarine;
            btn.colors = colors;

            var txt = Label(go.transform, "Text", label, 22, TextAlignmentOptions.Center, MoonWhite);
            Stretch(txt.rectTransform);
            return btn;
        }

        public static TMP_InputField InputField(Transform parent, string name, string placeholder,
            Vector2 size, bool isPassword = false)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var rt = go.AddComponent<RectTransform>();
            rt.sizeDelta = size;
            var img = go.AddComponent<Image>();
            img.color = GlassWhite(0.08f);
            ApplyMaterial(img);
            AddSilverBorder(rt);

            var input = go.AddComponent<TMP_InputField>();

            var textArea = new GameObject("Text Area");
            textArea.transform.SetParent(go.transform, false);
            var areaRt = textArea.AddComponent<RectTransform>();
            Stretch(areaRt);
            areaRt.offsetMin = new Vector2(10, 6);
            areaRt.offsetMax = new Vector2(-10, -6);
            textArea.AddComponent<RectMask2D>();

            var textGo = new GameObject("Text");
            textGo.transform.SetParent(textArea.transform, false);
            var tmp = textGo.AddComponent<TextMeshProUGUI>();
            tmp.fontSize = 22;
            tmp.color = MoonWhite;
            ApplyFont(tmp);
            Stretch(tmp.rectTransform);

            var phGo = new GameObject("Placeholder");
            phGo.transform.SetParent(textArea.transform, false);
            var ph = phGo.AddComponent<TextMeshProUGUI>();
            ph.text = placeholder;
            ph.fontSize = 22;
            ph.color = new Color(0.898f, 0.918f, 0.969f, 0.45f);
            ApplyFont(ph);
            Stretch(ph.rectTransform);

            input.textViewport = areaRt;
            input.textComponent = tmp;
            input.placeholder = ph;
            input.contentType = isPassword ? TMP_InputField.ContentType.Password
                                           : TMP_InputField.ContentType.Standard;
            return input;
        }

        /// <summary>Creates a vertical ScrollRect with a Content panel (VerticalLayoutGroup).</summary>
        public static (ScrollRect scroll, RectTransform content) ScrollView(Transform parent, string name,
            Vector2 anchorMin, Vector2 anchorMax, Vector2 size)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var rt = go.AddComponent<RectTransform>();
            rt.anchorMin = anchorMin;
            rt.anchorMax = anchorMax;
            rt.sizeDelta = size;
            var img = go.AddComponent<Image>();
            img.color = Glass(0.55f);
            ApplyMaterial(img);
            var scroll = go.AddComponent<ScrollRect>();
            scroll.horizontal = false;

            var vp = new GameObject("Viewport");
            vp.transform.SetParent(go.transform, false);
            var vpRt = vp.AddComponent<RectTransform>();
            Stretch(vpRt);
            // RectMask2D (CPU culling), NOT Mask (stencil): the built
            // player has no working stencil path for the baked UI material
            // (the UGUI package cache is a stub with no runtime UI shaders),
            // so a stencil Mask makes ALL scroll content invisible — the
            // layout is correct but nothing renders (found via the Details
            // overlay screenshot, 2026-11-16). RectMask2D is also what
            // Unity's own ScrollView prefab uses on its viewport.
            vp.AddComponent<RectMask2D>();
            var vpImg = vp.AddComponent<Image>();
            vpImg.color = Color.clear;
            ApplyMaterial(vpImg);
            scroll.viewport = vpRt;

            var content = new GameObject("Content");
            content.transform.SetParent(vp.transform, false);
            var cRt = content.AddComponent<RectTransform>();
            cRt.anchorMin = new Vector2(0, 1);
            cRt.anchorMax = new Vector2(1, 1);
            cRt.pivot = new Vector2(0.5f, 1);
            cRt.sizeDelta = new Vector2(0, 0);
            var layout = content.AddComponent<VerticalLayoutGroup>();
            layout.padding = new RectOffset(8, 8, 8, 8);
            layout.spacing = 8;
            layout.childControlWidth = true;
            layout.childControlHeight = false;
            layout.childForceExpandWidth = true;
            layout.childForceExpandHeight = false;
            content.AddComponent<ContentSizeFitter>().verticalFit = ContentSizeFitter.FitMode.PreferredSize;
            scroll.content = cRt;
            return (scroll, cRt);
        }

        public static void ClearChildren(Transform t)
        {
            for (int i = t.childCount - 1; i >= 0; i--)
                Object.Destroy(t.GetChild(i).gameObject);
        }

        /// <summary>Finds the SCENE's Canvas (named "Canvas" in every scene file).
        /// FindObjectOfType&lt;Canvas&gt;() returns the ToastCanvas instead — it is
        /// created first by the DontDestroyOnLoad GameManager — so screens must
        /// use this to parent their UI to the scene canvas. Building screen UI
        /// under the ToastCanvas would make it survive scene loads and pile up.</summary>
        public static Canvas SceneCanvas()
        {
            var go = GameObject.Find("Canvas");
            if (go != null) return go.GetComponent<Canvas>();
            return Object.FindObjectOfType<Canvas>();
        }

        /// <summary>Standard screen scaffold: full-screen dark background + top bar with title + back button.</summary>
        public static (GameObject root, GameObject topBar) ScreenBase(Transform canvas, string title,
            System.Action onBack)
        {
            // Background first: it is the backdrop the translucent root panel
            // sits on. (It must be added BEFORE the root, so it renders behind
            // it — adding it after the root would cover the whole screen with
            // an opaque panel and hide every control.)
            AddBackground(canvas, "Default", DeepUltramarine);

            var root = new GameObject("Screen");
            root.transform.SetParent(canvas, false);
            var rootRt = root.AddComponent<RectTransform>();
            Stretch(rootRt);
            var rootImg = root.AddComponent<Image>();
            rootImg.color = Glass(0.82f);
            ApplyMaterial(rootImg);

            var top = Panel(root.transform, "TopBar",
                new Vector2(0, 1), new Vector2(1, 1), new Vector2(0, 64),
                Glass(0.92f));
            var topRt = top.GetComponent<RectTransform>();
            topRt.pivot = new Vector2(0.5f, 1);
            topRt.anchoredPosition = Vector2.zero;

            var titleLabel = Label(top.transform, "Title", title, 26,
                TextAlignmentOptions.Left, MoonWhite, true);
            Place(titleLabel.rectTransform, 76, -14, 700, 40);

            if (onBack != null)
            {
                var back = Button(top.transform, "BackButton", "← 返回", new UnityAction(onBack), new Vector2(110, 44));
                var bRt = back.GetComponent<RectTransform>();
                bRt.anchorMin = new Vector2(0, 0.5f);
                bRt.anchorMax = new Vector2(0, 0.5f);
                bRt.pivot = new Vector2(0, 0.5f);
                bRt.anchoredPosition = new Vector2(12, 0);
            }
            return (root, top);
        }
    }
}
